package com.kavi.kavimart.controller;

import com.kavi.kavimart.dto.UserResponseDTO;import com.kavi.kavimart.service.CartService;import com.kavi.kavimart.util.SessionKeys;import javax.servlet.*;import javax.servlet.http.*;import java.math.BigDecimal;import java.util.List;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;
class CartServletTest {
 @Test void cartPageLoadsOnlyTheSignedInBuyersCart()throws Exception{ServletContext context=mock(ServletContext.class);CartService carts=mock(CartService.class);when(context.getAttribute(SessionKeys.CART_SERVICE)).thenReturn(carts);ServletConfig config=mock(ServletConfig.class);when(config.getServletContext()).thenReturn(context);CartServlet servlet=new CartServlet();servlet.init(config);HttpServletRequest req=mock(HttpServletRequest.class);HttpServletResponse res=mock(HttpServletResponse.class);HttpSession session=mock(HttpSession.class);RequestDispatcher dispatcher=mock(RequestDispatcher.class);when(req.getSession(false)).thenReturn(session);when(session.getAttribute(SessionKeys.USER)).thenReturn(new UserResponseDTO(4,"Buyer","buyer@example.com","BUYER",true));when(carts.getItems(4)).thenReturn(List.of());when(carts.total(4)).thenReturn(BigDecimal.ZERO);when(req.getRequestDispatcher("/WEB-INF/jsp/buyer/cart.jsp")).thenReturn(dispatcher);servlet.doGet(req,res);verify(req).setAttribute("items",List.of());verify(req).setAttribute("total",BigDecimal.ZERO);verify(dispatcher).forward(req,res);}
}
